<?php $title='Events'; require 'config/config.php'; require_login(); $events=$pdo->query('SELECT * FROM events ORDER BY event_date')->fetchAll(); require 'includes/header.php'; ?><section class="section"><div class="container"><h1>Upcoming Events</h1><div class="cards"><?php foreach($events as $ev): ?><article class="card"><div class="cardbody"><span class="date"><?=e(date('M d, Y',strtotime($ev['event_date'])))?></span><h2><?=e($ev['title'])?></h2><p>📍 <?=e($ev['location'])?></p><p class="muted"><?=e($ev['description'])?></p></div></article><?php endforeach; ?></div></div></section><?php require 'includes/footer.php'; ?>
